let objs = [];
let objsNum = 70;

const palette = ["#FF00D8", "#FFB201", "#98FF00", "#00FFC4", "#0082FE", "#B733FF"];

function setup() {
  createCanvas(windowWidth, windowHeight);
  angleMode(DEGREES);
  noFill();

  background(20);

  for (let i = 0; i < objsNum; i++) {
    objs.push(new Obj(i));
  }
}

function draw() {
  blendMode(BLEND);
  background(20, 50);

  blendMode(ADD);

  for (let i = 0; i < objs.length; i++) {
    objs[i].move();
    objs[i].display();
  }
}

class Obj {
  constructor(tmpIndex) {
    this.index = tmpIndex;
    this.startX = random(width);
    this.init();
    this.goalX = this.startX + this.rangeX;
  }

  init() {
    this.rangeX = random(10, 200);
    this.step = random(5, 10);
    this.strWeight = random(1, 15);
    this.c = color(random(palette));
    this.c.setAlpha(50);
  }

  move() {
    this.startX += this.step;
    this.goalX = this.startX + this.rangeX;

    if (this.startX > width) {
      this.init();
      this.startX = -this.rangeX;
      this.goalX = this.startX + this.rangeX;
    }
  }

  display() {
    strokeWeight(this.strWeight);
    stroke(this.c);
    beginShape();
    for (let x = this.startX; x <= this.goalX; x++) {
      let y = map(noise(x * 0.001, this.index * 0.1, frameCount * 0.002), 0, 1, -height * 0.25, height * 1.25);
      vertex(x, y);
    }
    endShape();
  }
}
